import React, { useState } from 'react';
import { View, Text, Image, TouchableOpacity, Modal, TextInput, ScrollView, StyleSheet, ActivityIndicator, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as ImagePicker from 'expo-image-picker';
import { addDoc, collection, serverTimestamp } from 'firebase/firestore';
import { db } from '../config';
import { BRAND } from './theme';

const CLOUD_NAME = 'faqfo0lu';
const UPLOAD_PRESET = 'flevora_upload';
const FILTERS = [
  { name: 'Normal', fx: '', tint: 'transparent' },
    { name: 'Vivid', fx: 'e_vibrance:60,e_contrast:15', tint: 'rgba(139,92,246,0.14)' },
      { name: 'B&W', fx: 'e_grayscale', tint: 'rgba(17,24,39,0.45)' },
        { name: 'Vintage', fx: 'e_sepia:70', tint: 'rgba(180,83,9,0.25)' },
          { name: 'Warm', fx: 'e_tint:35:ff8800', tint: 'rgba(249,115,22,0.2)' },
            { name: 'Cool', fx: 'e_tint:35:0088ff', tint: 'rgba(59,130,246,0.2)' },
            ];

            export function StoryCreatorModal({ visible, uid, me, onClose }: { visible: boolean; uid: string; me: any; onClose: () => void }) {
              const [uri, setUri] = useState('');
                const [mType, setMType] = useState<'image' | 'video'>('image');
                  const [fxIdx, setFxIdx] = useState(0);
                    const [showText, setShowText] = useState(false);
                      const [caption, setCaption] = useState('');
                        const [shareOpen, setShareOpen] = useState(false);
                          const [cfOnly, setCfOnly] = useState(false);
                            const [busy, setBusy] = useState(false);

                              const resetAndClose = () => { setUri(''); setFxIdx(0); setCaption(''); setShowText(false); setShareOpen(false); onClose(); };

                                const pick = async (fromCam: boolean) => {
                                    if (fromCam) {
                                          const p = await ImagePicker.requestCameraPermissionsAsync();
                                                if (!p.granted) return Alert.alert('Permission Needed', 'Allow camera access.');
                                                    }
                                                        const fn = fromCam ? ImagePicker.launchCameraAsync : ImagePicker.launchImageLibraryAsync;
                                                            const res = await fn({ mediaTypes: ['images', 'videos'], quality: 0.7 });
                                                                if (!res.canceled && res.assets[0]) {
                                                                      setUri(res.assets[0].uri);
                                                                            setMType(res.assets[0].type === 'video' ? 'video' : 'image');
                                                                                }
                                                                                  };

                                                                                    const publish = async (closeFriends: boolean) => {
                                                                                        if (!uri || !uid || busy) return;
                                                                                            setBusy(true);
                                                                                                try {
                                                                                                      const data = new FormData();
                                                                                                            data.append('file', { uri, type: mType === 'video' ? 'video/mp4' : 'image/jpeg', name: `story_${Date.now()}` } as any);
                                                                                                                  data.append('upload_preset', UPLOAD_PRESET);
                                                                                                                        const res = await fetch(`https://api.cloudinary.com/v1_1/${CLOUD_NAME}/${mType}/upload`, { method: 'POST', body: data });
                                                                                                                              const json = await res.json();
                                                                                                                                    if (!json.secure_url) throw new Error('fail');
                                                                                                                                          const fx = mType === 'image' ? FILTERS[fxIdx].fx : '';
                                                                                                                                                const finalUrl = fx ? json.secure_url.replace('/upload/', `/upload/${fx}/`) : json.secure_url;
                                                                                                                                                      await addDoc(collection(db, 'stories'), {
                                                                                                                                                              uid, username: me?.username || 'user', mediaUrl: finalUrl, mediaType: mType,
                                                                                                                                                                      caption: caption.trim(), closeFriendsOnly: closeFriends,
                                                                                                                                                                              allowedUids: closeFriends ? (me?.closeFriends || []) : [],
                                                                                                                                                                                      viewers: [], viewerNames: [], expiresAt: Date.now() + 86400000, createdAt: serverTimestamp(),
                                                                                                                                                                                            });
                                                                                                                                                                                                  Alert.alert('Story Added', closeFriends ? 'Shared with Close Friends ★' : 'Shared to Your story!');
                                                                                                                                                                                                        resetAndClose();
                                                                                                                                                                                                            } catch {
                                                                                                                                                                                                                  Alert.alert('Upload Failed', 'Could not upload story.');
                                                                                                                                                                                                                      } finally { setBusy(false); }
                                                                                                                                                                                                                        };

                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                              <Modal visible={visible} animationType="slide">
                                                                                                                                                                                                                                    <View style={styles.wrap}>
                                                                                                                                                                                                                                            {!uri ? (
                                                                                                                                                                                                                                                      <View style={styles.pickWrap}>
                                                                                                                                                                                                                                                                  <View style={styles.top}>
                                                                                                                                                                                                                                                                                <TouchableOpacity hitSlop={12} onPress={resetAndClose}><Ionicons name="close" size={28} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                              <Text style={styles.head}>Add to story</Text>
                                                                                                                                                                                                                                                                                                            <View style={{ width: 28 }} />
                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                    <View style={styles.cardRow}>
                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity style={styles.bigCard} onPress={() => pick(true)}>
                                                                                                                                                                                                                                                                                                                                                                  <Ionicons name="camera" size={38} color="#fff" />
                                                                                                                                                                                                                                                                                                                                                                                  <Text style={styles.cardTxt}>Camera</Text>
                                                                                                                                                                                                                                                                                                                                                                                                </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={styles.bigCard} onPress={() => pick(false)}>
                                                                                                                                                                                                                                                                                                                                                                                                                              <Ionicons name="images" size={38} color={BRAND} />
                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={styles.cardTxt}>Gallery</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={{ flex: 1 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Image source={{ uri }} style={styles.fullImg} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={[StyleSheet.absoluteFillObject, { backgroundColor: FILTERS[fxIdx].tint }]} pointerEvents="none" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={styles.edTop}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity hitSlop={12} onPress={() => setUri('')}><Ionicons name="arrow-back" size={26} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={styles.aaBtn} onPress={() => setShowText(!showText)}><Text style={{ color: '#fff', fontWeight: '800', fontSize: 16 }}>Aa</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {showText && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TextInput style={styles.txtOverlay} placeholder="Add text..." placeholderTextColor="#D1D5DB" value={caption} onChangeText={setCaption} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {mType === 'image' && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.fxBar}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {FILTERS.map((f, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity key={f.name} onPress={() => setFxIdx(i)} style={[styles.fxChip, fxIdx === i && { borderColor: BRAND, backgroundColor: '#1E1B4B' }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={{ color: '#fff', fontSize: 12, fontWeight: '700' }}>{f.name}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </ScrollView>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={styles.bottomBar}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity style={styles.audBtn} onPress={() => publish(false)} disabled={busy}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Ionicons name="person-circle" size={20} color="#fff" /><Text style={styles.audTxt}>Your story</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity style={styles.audBtn} onPress={() => publish(true)} disabled={busy}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Ionicons name="star" size={18} color="#10B981" /><Text style={styles.audTxt}>Close Friends</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={styles.goBtn} onPress={() => setShareOpen(true)} disabled={busy}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {busy ? <ActivityIndicator color="#fff" /> : <Ionicons name="chevron-forward" size={22} color="#fff" />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Modal visible={shareOpen} animationType="slide" transparent>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.shBg}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={styles.shCard}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={styles.shTitle}>Share</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={styles.shRow} onPress={() => setCfOnly(false)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Ionicons name="person-circle" size={32} color={BRAND} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Text style={styles.shLbl}>Your story</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Ionicons name={cfOnly ? 'radio-button-off' : 'radio-button-on'} size={22} color="#111827" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity style={styles.shRow} onPress={() => setCfOnly(true)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Ionicons name="star-outline" size={30} color="#10B981" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={styles.shLbl}>Close Friends</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Ionicons name={cfOnly ? 'radio-button-on' : 'radio-button-off'} size={22} color="#111827" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity style={styles.shBtn} onPress={() => { setShareOpen(false); publish(cfOnly); }} disabled={busy}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {busy ? <ActivityIndicator color="#fff" /> : <Text style={{ color: '#fff', fontWeight: '800', fontSize: 16 }}>Share</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            wrap: { flex: 1, backgroundColor: '#000' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              pickWrap: { flex: 1, paddingTop: 48, paddingHorizontal: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 40 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  head: { color: '#fff', fontSize: 18, fontWeight: '800' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cardRow: { flexDirection: 'row', gap: 14, marginTop: 40 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      bigCard: { flex: 1, height: 180, backgroundColor: '#18181B', borderRadius: 18, justifyContent: 'center', alignItems: 'center', gap: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cardTxt: { color: '#fff', fontWeight: '700', fontSize: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fullImg: { flex: 1, resizeMode: 'contain' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            edTop: { position: 'absolute', top: 48, left: 16, right: 16, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              aaBtn: { width: 38, height: 38, borderRadius: 19, backgroundColor: 'rgba(0,0,0,0.55)', justifyContent: 'center', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                txtOverlay: { position: 'absolute', top: '42%', alignSelf: 'center', backgroundColor: 'rgba(0,0,0,0.6)', color: '#fff', paddingHorizontal: 16, paddingVertical: 10, borderRadius: 12, fontSize: 18, fontWeight: '700', minWidth: 200, textAlign: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fxBar: { position: 'absolute', bottom: 86, left: 12, right: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fxChip: { paddingHorizontal: 14, paddingVertical: 7, borderRadius: 16, backgroundColor: 'rgba(24,24,27,0.85)', borderWidth: 1.5, borderColor: '#3F3F46', marginRight: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      bottomBar: { position: 'absolute', bottom: 24, left: 12, right: 12, flexDirection: 'row', alignItems: 'center', gap: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        audBtn: { flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, backgroundColor: '#27272A', paddingVertical: 12, borderRadius: 24 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          audTxt: { color: '#fff', fontWeight: '700', fontSize: 13 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            goBtn: { width: 46, height: 46, borderRadius: 23, backgroundColor: '#3B82F6', justifyContent: 'center', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              shBg: { flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'flex-end' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                shCard: { backgroundColor: '#fff', borderTopLeftRadius: 22, borderTopRightRadius: 22, padding: 20 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  shTitle: { fontSize: 18, fontWeight: '800', textAlign: 'center', marginBottom: 16, color: '#111827' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    shRow: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      shLbl: { flex: 1, fontSize: 16, fontWeight: '600', color: '#111827' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        shBtn: { backgroundColor: '#3B82F6', padding: 14, borderRadius: 14, alignItems: 'center', marginTop: 14, marginBottom: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        